def main():
    target_path = os.path.join(os.path.dirname(__file__), "..", "backend", "data", "evaluation_dataset.json")
    os.makedirs(os.path.dirname(target_path), exist_ok=True)
    with open(target_path, "w", encoding="utf-8") as f:
        json.dump(examples, f, indent=2, ensure_ascii=False)
    print(f"Generated {len(examples)} evaluation examples saved to {target_path}")

if __name__ == "__main__":
    main()
